// Build the file://-compatible single-script package for the image studio.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const publicDir=path.join(root,'public');
const read=name=>fs.readFileSync(path.join(publicDir,name),'utf8');
const sources=['chat-images-core.js','chat-images-store.js','chat-images.js'];
const content=Object.fromEntries(sources.map(name=>[name,read(name)]));
const exportNames=source=>{
  const names=new Set();
  for(const match of source.matchAll(/export\s+(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/g))names.add(match[1]);
  for(const match of source.matchAll(/export\s+(?:const|let|var|class)\s+([A-Za-z_$][\w$]*)/g))names.add(match[1]);
  for(const match of source.matchAll(/export\s*\{([^}]+)\}/g))for(const part of match[1].split(',')){const name=part.trim().split(/\s+as\s+/).pop();if(name)names.add(name);}
  return [...names];
};
const strip=source=>source.replace(/^\s*export\s+(?=(?:async\s+)?function|const|let|var|class)/gm,'').replace(/^\s*export\s*\{[^}]*\}\s*;?\s*$/gm,'').replace(/^\s*export\s+default\s+/gm,'var __default = ');
const imports={
  './chat-images-core.js':exportNames(content['chat-images-core.js']),
  './chat-images-store.js':exportNames(content['chat-images-store.js'])
};
const found=new Set();
const app=content['chat-images.js'].replace(/^import\s*\{([^}]+)\}\s*from\s*['"](\.\/chat-images-(?:core|store)\.js)(?:\?v=[a-f0-9]{8})?['"];?[ \t]*$/gm, (whole,requested,module)=>{
  const names=imports[module];
  if(found.has(module)||requested.split(',').map(value=>value.trim()).some(name=>!names.includes(name)))throw new Error(`Unsupported import for ${module}`);
  found.add(module);
  return '';
});
for(const module of Object.keys(imports))if(!found.has(module))throw new Error(`Missing supported import for ${module}`);
if(/^import\s/m.test(app))throw new Error('Unsupported import remains in chat-images.js');
const bundle=`/* Generated by tools/build-chat-images-file-bundle.mjs; do not edit. */\n(function(){\n'use strict';\n/* chat-images-core.js */\n${strip(content['chat-images-core.js'])}\n/* chat-images-store.js */\n${strip(content['chat-images-store.js'])}\n/* chat-images.js */\n${app}\n})();\n`;
const output=path.join(publicDir,'chat-images-file-bundle.js');
if(process.argv.includes('--check')){
  if(!fs.existsSync(output)||read('chat-images-file-bundle.js').replace(/\r\n/g,'\n')!==bundle.replace(/\r\n/g,'\n'))throw new Error('Image studio file package is stale; run node tools/build-chat-images-file-bundle.mjs');
  console.log('PASS image studio file package matches current sources');
}else{
  fs.writeFileSync(output,bundle,'utf8');
  console.log(`Built public/chat-images-file-bundle.js (${(Buffer.byteLength(bundle)/1024).toFixed(1)} KiB)`);
}
